/**
 * 🔧 WEBSOCKET BROADCASTING FIX
 * Add this to your ogzprime_ssl_server_advanced.js
 * 
 * Problem: Data coming from Polygon but not reaching public clients
 * Solution: Ensure proper broadcasting to ALL connected clients
 */

// 1. ADD CLIENT TRACKING
const connectedClients = new Map();
let clientIdCounter = 0;

// 2. ENHANCED CONNECTION HANDLER
wss.on('connection', (ws, req) => {
  const clientId = ++clientIdCounter;
  const clientIp = req.headers['x-forwarded-for'] || req.socket.remoteAddress;

  // Store client info
  const clientInfo = {
    id: clientId,
    ws: ws,
    ip: clientIp,
    connectedAt: Date.now(),
    type: 'unknown',
    isAlive: true
  };

  connectedClients.set(clientId, clientInfo);

  console.log(`✅ Client #${clientId} connected from ${clientIp}`);
  console.log(`📊 Total clients: ${connectedClients.size}`);

  // Send welcome message
  ws.send(JSON.stringify({
    type: 'welcome',
    clientId: clientId,
    message: 'Connected to OGZ Prime WebSocket',
    timestamp: Date.now()
  }));

  // Heartbeat
  ws.isAlive = true;
  ws.on('pong', () => {
    ws.isAlive = true;
  });

  // Handle messages
  ws.on('message', (message) => {
    try {
      const data = JSON.parse(message.toString());

      // Update client type
      if (data.type === 'identify') {
        clientInfo.type = data.source || 'unknown';
        console.log(`🏷️ Client #${clientId} identified as: ${clientInfo.type}`);
      }

      // Handle ping/pong
      if (data.type === 'ping') {
        ws.send(JSON.stringify({
          type: 'pong',
          timestamp: Date.now()
        }));
      }

    } catch (err) {
      console.error(`❌ Error from client #${clientId}:`, err);
    }
  });

  // Handle disconnection
  ws.on('close', () => {
    connectedClients.delete(clientId);
    console.log(`🔌 Client #${clientId} disconnected`);
    console.log(`📊 Remaining clients: ${connectedClients.size}`);
  });

  ws.on('error', (err) => {
    console.error(`❌ WebSocket error for client #${clientId}:`, err);
  });
});

// 3. FIXED BROADCAST FUNCTION
function broadcastToAllClients(data) {
  const message = JSON.stringify(data);
  let sentCount = 0;
  let errorCount = 0;

  // Log what we're broadcasting
  if (data.type === 'price') {
    console.log(`📡 Broadcasting price: ${data.data.asset} $${data.data.price?.toFixed(2)}`);
  }

  // Send to ALL connected clients
  connectedClients.forEach((clientInfo, clientId) => {
    try {
      if (clientInfo.ws.readyState === WebSocket.OPEN) {
        clientInfo.ws.send(message);
        sentCount++;
      } else {
        // Remove dead connections
        connectedClients.delete(clientId);
      }
    } catch (err) {
      console.error(`❌ Error sending to client #${clientId}:`, err);
      errorCount++;
      // Remove problematic client
      connectedClients.delete(clientId);
    }
  });

  // Log broadcast results
  if (sentCount > 0 || errorCount > 0) {
    console.log(`📨 Broadcast complete: ${sentCount} sent, ${errorCount} errors, ${connectedClients.size} total clients`);
  }

  return { sent: sentCount, errors: errorCount };
}

// 4. FIX POLYGON MESSAGE HANDLER
polygonSocket.on('message', (data) => {
  try {
    const messages = JSON.parse(data);
    const msgArray = Array.isArray(messages) ? messages : [messages];

    for (const msg of msgArray) {
      if (msg.ev === 'XA' && msg.c && msg.e) {
        tickCount++;
        const price = parseFloat(msg.c);

        // Determine asset
        let asset = 'BTC-USD';
        if (msg.pair) {
          asset = msg.pair.includes('-') ? msg.pair : msg.pair.replace('USD', '-USD');
        }

        // Store price
        assetPrices[asset] = price;
        if (asset === currentAsset) {
          lastKnownPrice = price;
        }

        // Log every 10th tick
        if (tickCount % 10 === 0) {
          console.log(`💰 ${asset}: $${price.toFixed(2)} (tick #${tickCount})`);
        }

        // CRITICAL: Broadcast to ALL clients
        const priceMessage = {
          type: 'price',
          data: {
            asset: asset,
            price: price,
            timestamp: Date.now(),
            allPrices: assetPrices,
            tickCount: tickCount
          }
        };

        // Use our fixed broadcast function
        broadcastToAllClients(priceMessage);
      }
    }
  } catch (err) {
    console.error('❌ Polygon data error:', err);
  }
});

// 5. HEARTBEAT TO KEEP CONNECTIONS ALIVE
const heartbeatInterval = setInterval(() => {
  connectedClients.forEach((clientInfo, clientId) => {
    if (clientInfo.ws.isAlive === false) {
      console.log(`💔 Removing dead client #${clientId}`);
      clientInfo.ws.terminate();
      connectedClients.delete(clientId);
      return;
    }

    clientInfo.ws.isAlive = false;
    clientInfo.ws.ping();
  });
}, 30000); // Every 30 seconds

// 6. STATUS MONITORING
setInterval(() => {
  const clientTypes = {};
  connectedClients.forEach(client => {
    clientTypes[client.type] = (clientTypes[client.type] || 0) + 1;
  });

  console.log('\n📊 === WEBSOCKET STATUS ===');
  console.log(`Connected clients: ${connectedClients.size}`);
  console.log(`Client types:`, clientTypes);
  console.log(`Price ticks: ${tickCount}`);
  console.log(`Last price: $${lastKnownPrice?.toFixed(2) || 'N/A'}`);
  console.log('========================\n');
}, 60000); // Every minute

// 7. ENSURE CLEAN SHUTDOWN
process.on('SIGINT', () => {
  console.log('\n🛑 Shutting down WebSocket server...');

  // Notify all clients
  broadcastToAllClients({
    type: 'server_shutdown',
    message: 'Server is shutting down',
    timestamp: Date.now()
  });

  // Close all connections
  connectedClients.forEach((clientInfo) => {
    clientInfo.ws.close(1000, 'Server shutdown');
  });

  clearInterval(heartbeatInterval);
  process.exit(0);
});

// 8. TEST ENDPOINT TO VERIFY BROADCASTING
app.get('/api/test-broadcast', (req, res) => {
  const testMessage = {
    type: 'test',
    message: 'Test broadcast from server',
    timestamp: Date.now(),
    connectedClients: connectedClients.size
  };

  const result = broadcastToAllClients(testMessage);

  res.json({
    success: true,
    broadcast: result,
    clients: connectedClients.size,
    lastPrice: lastKnownPrice
  });
});

