// KrakenAdapter.js - Kraken Exchange broker adapter
// Handles cryptocurrency trading through Kraken's API

const BaseBrokerAdapter = require('./BaseBrokerAdapter');
const crypto = require('crypto');
const axios = require('axios');
const querystring = require('querystring');

/**
 * Kraken Exchange Broker Adapter
 * Supports cryptocurrency trading
 */
class KrakenAdapter extends BaseBrokerAdapter {
  constructor(config = {}) {
    super({
      name: 'kraken',
      baseUrl: 'https://api.kraken.com',
      maxRequestsPerSecond: 1, // Kraken has strict rate limits
      ...config
    });

    // Kraken-specific capabilities
    this.capabilities = {
      markets: ['crypto'],
      orderTypes: ['market', 'limit', 'stop-loss', 'take-profit'],
      timeInForce: ['GTC', 'IOC', 'FOK'],
      streaming: false,
      paperTrading: false,
      fractionalShares: true,
      crypto: true,
      options: false,
      forex: false
    };

    // API client
    this.client = null;

    // Kraken-specific state
    this.nonce = Date.now();
    this.assetPairs = new Map();
  }

  /**
   * Connect to Kraken
   * @returns {Promise<boolean>} Connection success
   */
  async connect() {
    try {
      this.log('info', 'Connecting to Kraken...');

      // Validate credentials
      if (!this.config.apiKey || !this.config.apiSecret) {
        throw new Error('API key and secret are required');
      }

      // Setup HTTP client
      this.client = axios.create({
        baseURL: this.config.baseUrl,
        timeout: this.config.connectionTimeout
      });

      // Test connection by getting server time
      const response = await this.client.get('/0/public/Time');

      if (response.data.error && response.data.error.length > 0) {
        throw new Error(`Kraken API error: ${response.data.error.join(', ')}`);
      }

      // Load asset pairs for symbol validation
      await this.loadAssetPairs();

      // Test private API access
      const balanceResponse = await this.makePrivateRequest('/0/private/Balance');

      this.setConnected(true);
      this.resetConnectionAttempts();

      this.log('info', 'Successfully connected to Kraken', {
        serverTime: response.data.result.unixtime,
        assets: this.assetPairs.size
      });

      return true;
    } catch (error) {
      this.log('error', 'Failed to connect to Kraken', { error: error.message });
      await this.handleConnectionError(error);
      return false;
    }
  }

  /**
   * Load asset pairs from Kraken
   * @private
   */
  async loadAssetPairs() {
    try {
      const response = await this.client.get('/0/public/AssetPairs');

      if (response.data.error && response.data.error.length > 0) {
        throw new Error(`Failed to load asset pairs: ${response.data.error.join(', ')}`);
      }

      this.assetPairs.clear();
      for (const [pairName, pairInfo] of Object.entries(response.data.result)) {
        this.assetPairs.set(pairName, pairInfo);
      }

      this.log('info', `Loaded ${this.assetPairs.size} asset pairs`);
    } catch (error) {
      this.log('error', 'Failed to load asset pairs', { error: error.message });
      throw error;
    }
  }

  /**
   * Disconnect from Kraken
   * @returns {Promise<boolean>} Disconnection success
   */
  async disconnect() {
    try {
      this.log('info', 'Disconnecting from Kraken...');

      // Clear client and state
      this.client = null;
      this.assetPairs.clear();

      this.setConnected(false);
      this.log('info', 'Disconnected from Kraken');

      return true;
    } catch (error) {
      this.log('error', 'Error disconnecting from Kraken', { error: error.message });
      return false;
    }
  }

  /**
   * Place an order on Kraken
   * @param {Object} order - Order parameters
   * @returns {Promise<Object>} Order result
   */
  async placeOrder(order) {
    try {
      // Validate order
      const validation = this.validateOrder(order);
      if (!validation.valid) {
        throw new Error(`Order validation failed: ${validation.errors.join(', ')}`);
      }

      // Check rate limit
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      // Convert symbol to Kraken format
      const krakenSymbol = this.convertToKrakenSymbol(order.symbol);
      if (!krakenSymbol) {
        throw new Error(`Unsupported symbol: ${order.symbol}`);
      }

      // Prepare Kraken order
      const krakenOrder = {
        pair: krakenSymbol,
        type: order.side,
        ordertype: this.convertOrderType(order.type),
        volume: order.quantity.toString()
      };

      // Add price for limit orders
      if (order.type === 'limit' && order.price) {
        krakenOrder.price = order.price.toString();
      }

      // Add client order ID if provided
      if (order.clientOrderId) {
        krakenOrder.userref = order.clientOrderId;
      }

      this.log('info', 'Placing order', { order: krakenOrder });

      // Submit order
      const response = await this.makePrivateRequest('/0/private/AddOrder', krakenOrder);

      if (response.error && response.error.length > 0) {
        throw new Error(`Kraken order error: ${response.error.join(', ')}`);
      }

      // Extract order ID from response
      const orderId = response.result.txid[0];

      // Get full order details
      const orderDetails = await this.getOrder(orderId);

      this.log('info', 'Order placed successfully', { 
        orderId,
        symbol: order.symbol,
        side: order.side,
        quantity: order.quantity
      });

      // Emit order placed event
      this.emit('orderPlaced', orderDetails);

      return orderDetails;
    } catch (error) {
      this.log('error', 'Failed to place order', { 
        error: error.message,
        order 
      });
      throw new Error(`Kraken order failed: ${error.message}`);
    }
  }

  /**
   * Cancel an order
   * @param {string} orderId - Order ID to cancel
   * @returns {Promise<Object>} Cancellation result
   */
  async cancelOrder(orderId) {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      this.log('info', 'Cancelling order', { orderId });

      const response = await this.makePrivateRequest('/0/private/CancelOrder', {
        txid: orderId
      });

      if (response.error && response.error.length > 0) {
        throw new Error(`Kraken cancel error: ${response.error.join(', ')}`);
      }

      this.log('info', 'Order cancelled successfully', { orderId });

      this.emit('orderCancelled', { orderId });

      return {
        orderId,
        status: 'cancelled',
        timestamp: Date.now()
      };
    } catch (error) {
      this.log('error', 'Failed to cancel order', { 
        orderId,
        error: error.message 
      });
      throw new Error(`Failed to cancel order: ${error.message}`);
    }
  }

  /**
   * Get current positions (balances for crypto)
   * @returns {Promise<Array>} Array of positions
   */
  async getPositions() {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('/0/private/Balance');

      if (response.error && response.error.length > 0) {
        throw new Error(`Kraken balance error: ${response.error.join(', ')}`);
      }

      const positions = [];

      for (const [asset, balance] of Object.entries(response.result)) {
        const balanceFloat = parseFloat(balance);

        if (balanceFloat > 0) {
          positions.push(this.normalizePosition({
            symbol: asset,
            quantity: balanceFloat,
            side: 'long',
            avgPrice: 0, // Not available from balance endpoint
            marketValue: 0, // Would need current prices
            unrealizedPnL: 0,
            realizedPnL: 0,
            lastPrice: 0
          }));
        }
      }

      return positions;
    } catch (error) {
      this.log('error', 'Failed to get positions', { error: error.message });
      throw new Error(`Failed to get positions: ${error.message}`);
    }
  }

  /**
   * Get account balance
   * @returns {Promise<Object>} Account balance information
   */
  async getAccountBalance() {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('/0/private/Balance');

      if (response.error && response.error.length > 0) {
        throw new Error(`Kraken balance error: ${response.error.join(', ')}`);
      }

      // Calculate total value in USD (simplified)
      let totalValue = 0;
      const usdBalance = parseFloat(response.result.ZUSD || 0);

      return this.normalizeBalance({
        cash: usdBalance,
        equity: totalValue || usdBalance,
        buyingPower: usdBalance,
        dayTradingBuyingPower: usdBalance,
        currency: 'USD'
      });
    } catch (error) {
      this.log('error', 'Failed to get account balance', { error: error.message });
      throw new Error(`Failed to get account balance: ${error.message}`);
    }
  }

  /**
   * Check if symbol is supported
   * @param {string} symbol - Trading symbol
   * @returns {boolean} Whether symbol is supported
   */
  supportsSymbol(symbol) {
    const krakenSymbol = this.convertToKrakenSymbol(symbol);
    return krakenSymbol !== null;
  }

  /**
   * Get order by ID
   * @param {string} orderId - Order ID
   * @returns {Promise<Object>} Order information
   */
  async getOrder(orderId) {
    try {
      if (!this.checkRateLimit()) {
        await this.waitForRateLimit();
      }

      const response = await this.makePrivateRequest('/0/private/QueryOrders', {
        txid: orderId
      });

      if (response.error && response.error.length > 0) {
        throw new Error(`Kraken query error: ${response.error.join(', ')}`);
      }

      const orderData = response.result[orderId];
      return this.normalizeKrakenOrder(orderId, orderData);
    } catch (error) {
      this.log('error', 'Failed to get order', { orderId, error: error.message });
      throw new Error(`Failed to get order: ${error.message}`);
    }
  }

  /**
   * Make authenticated request to Kraken
   * @param {string} endpoint - API endpoint
   * @param {Object} params - Request parameters
   * @returns {Promise<Object>} API response
   * @private
   */
  async makePrivateRequest(endpoint, params = {}) {
    // Increment nonce
    this.nonce++;

    // Add nonce to parameters
    const data = {
      nonce: this.nonce,
      ...params
    };

    // Create query string
    const postData = querystring.stringify(data);

    // Create signature
    const signature = this.createSignature(endpoint, postData);

    // Make request
    const response = await this.client.post(endpoint, postData, {
      headers: {
        'API-Key': this.config.apiKey,
        'API-Sign': signature,
        'Content-Type': 'application/x-www-form-urlencoded'
      }
    });

    return response.data;
  }

  /**
   * Create API signature for Kraken
   * @param {string} endpoint - API endpoint
   * @param {string} postData - POST data
   * @returns {string} API signature
   * @private
   */
  createSignature(endpoint, postData) {
    const secret = Buffer.from(this.config.apiSecret, 'base64');
    const hash = crypto.createHash('sha256').update(this.nonce + postData).digest();
    const hmac = crypto.createHmac('sha512', secret);

    hmac.update(endpoint, 'utf8');
    hmac.update(hash);

    return hmac.digest('base64');
  }

  /**
   * Convert symbol to Kraken format
   * @param {string} symbol - Standard symbol (e.g., BTC-USD)
   * @returns {string|null} Kraken symbol or null if not supported
   * @private
   */
  convertToKrakenSymbol(symbol) {
    // Simple mapping - in production, use comprehensive symbol mapping
    const symbolMappings = {
      'BTC-USD': 'XBTUSD',
      'ETH-USD': 'ETHUSD',
      'ADA-USD': 'ADAUSD',
      'DOT-USD': 'DOTUSD',
      'LINK-USD': 'LINKUSD',
      'LTC-USD': 'LTCUSD',
      'XRP-USD': 'XRPUSD'
    };

    return symbolMappings[symbol] || null;
  }

  /**
   * Convert order type to Kraken format
   * @param {string} orderType - Standard order type
   * @returns {string} Kraken order type
   * @private
   */
  convertOrderType(orderType) {
    const typeMap = {
      'market': 'market',
      'limit': 'limit',
      'stop': 'stop-loss',
      'stop_limit': 'stop-loss-limit'
    };

    return typeMap[orderType] || 'market';
  }

  /**
   * Normalize Kraken order
   * @param {string} orderId - Order ID
   * @param {Object} krakenOrder - Kraken order data
   * @returns {Object} Normalized order
   * @private
   */
  normalizeKrakenOrder(orderId, krakenOrder) {
    return {
      orderId,
      clientOrderId: krakenOrder.userref || null,
      symbol: this.convertFromKrakenSymbol(krakenOrder.descr.pair),
      side: krakenOrder.descr.type,
      quantity: parseFloat(krakenOrder.vol),
      price: krakenOrder.descr.price ? parseFloat(krakenOrder.descr.price) : null,
      type: krakenOrder.descr.ordertype,
      status: this.normalizeKrakenOrderStatus(krakenOrder.status),
      fillPrice: krakenOrder.price ? parseFloat(krakenOrder.price) : null,
      filledQuantity: parseFloat(krakenOrder.vol_exec),
      timestamp: Math.floor(krakenOrder.opentm * 1000),
      fees: parseFloat(krakenOrder.fee || 0)
    };
  }

  /**
   * Convert from Kraken symbol format
   * @param {string} krakenSymbol - Kraken symbol
   * @returns {string} Standard symbol
   * @private
   */
  convertFromKrakenSymbol(krakenSymbol) {
    const reverseMap = {
      'XBTUSD': 'BTC-USD',
      'ETHUSD': 'ETH-USD',
      'ADAUSD': 'ADA-USD',
      'DOTUSD': 'DOT-USD',
      'LINKUSD': 'LINK-USD',
      'LTCUSD': 'LTC-USD',
      'XRPUSD': 'XRP-USD'
    };

    return reverseMap[krakenSymbol] || krakenSymbol;
  }

  /**
   * Normalize Kraken order status
   * @param {string} krakenStatus - Kraken order status
   * @returns {string} Normalized status
   * @private
   */
  normalizeKrakenOrderStatus(krakenStatus) {
    const statusMap = {
      'pending': 'pending',
      'open': 'pending',
      'closed': 'filled',
      'canceled': 'cancelled',
      'expired': 'expired'
    };

    return statusMap[krakenStatus] || 'unknown';
  }
}

module.exports = KrakenAdapter;

// OGZProfileExporter.js - Export/Import Hitch command chains as profiles
// Save your winning strategies and replay them anytime!

const fs = require('fs').promises;
const path = require('path');

class OGZProfileExporter {
  constructor(hitchNLP) {
    this.hitch = hitchNLP;
    this.profilesPath = path.join(process.cwd(), 'profiles', 'hitch');
    this.ensureProfileDirectory();
  }

  async ensureProfileDirectory() {
    await fs.mkdir(this.profilesPath, { recursive: true });
  }

  /**
   * Export top performing commands as a profile
   */
  async exportTopCommandsAsProfile(profileName, options = {}) {
    const {
      timeframe = 'weekly',  // daily, weekly, all-time
      minProfit = 2,         // minimum % profit to include
      maxCommands = 10       // max commands to export
    } = options;

    console.log(`ðŸ“¦ Exporting top commands to profile: ${profileName}`);

    // Get command history
    const history = await this.hitch.logger.getCommandHistory();

    // Filter and sort by profit
    const profitableCommands = history
      .filter(cmd => {
        if (!cmd.impact?.updates || cmd.impact.updates.length === 0) return false;

        const finalUpdate = cmd.impact.updates[cmd.impact.updates.length - 1];
        return finalUpdate.percentChange >= minProfit;
      })
      .sort((a, b) => {
        const aProfit = a.impact.updates[a.impact.updates.length - 1].percentChange;
        const bProfit = b.impact.updates[b.impact.updates.length - 1].percentChange;
        return bProfit - aProfit;
      })
      .slice(0, maxCommands);

    // Create profile structure
    const profile = {
      name: profileName,
      version: '1.0',
      created: new Date().toISOString(),
      description: `Top ${profitableCommands.length} profitable commands from ${timeframe} trading`,
      metadata: {
        totalProfit: this.calculateTotalProfit(profitableCommands),
        avgProfit: this.calculateAvgProfit(profitableCommands),
        timeframe: timeframe,
        commandCount: profitableCommands.length
      },
      commands: profitableCommands.map(cmd => ({
        input: cmd.input,
        sequence: cmd.id,
        impact: {
          percentChange: cmd.impact.updates[cmd.impact.updates.length - 1].percentChange,
          trades: cmd.impact.updates[cmd.impact.updates.length - 1].tradesExecuted
        },
        interpretation: cmd.results?.applied || [],
        timestamp: cmd.timestamp
      })),
      // Execution order (can be customized)
      executionChain: profitableCommands.map(cmd => cmd.input),
      // Conditional logic
      conditions: this.extractConditions(profitableCommands)
    };

    // Save profile
    const filename = `${profileName.toLowerCase().replace(/\s+/g, '_')}.ogzprofile`;
    const filepath = path.join(this.profilesPath, filename);

    await fs.writeFile(filepath, JSON.stringify(profile, null, 2));

    console.log(`âœ… Profile exported: ${filepath}`);
    console.log(`ðŸ“Š Contains ${profile.commands.length} commands with ${profile.metadata.avgProfit.toFixed(2)}% avg profit`);

    return {
      success: true,
      filepath: filepath,
      profile: profile
    };
  }

  /**
   * Import and execute a profile
   */
  async importAndExecuteProfile(profileNameOrPath, options = {}) {
    const {
      dryRun = false,        // Test without executing
      sequential = true,     // Execute commands in order
      delayBetween = 1000   // Delay between commands (ms)
    } = options;

    console.log(`ðŸ“¥ Importing profile: ${profileNameOrPath}`);

    // Load profile
    let profile;
    try {
      const filepath = profileNameOrPath.includes('.ogzprofile') 
        ? profileNameOrPath 
        : path.join(this.profilesPath, `${profileNameOrPath}.ogzprofile`);

      const content = await fs.readFile(filepath, 'utf8');
      profile = JSON.parse(content);
    } catch (error) {
      throw new Error(`Failed to load profile: ${error.message}`);
    }

    console.log(`ðŸ“‹ Profile: ${profile.name}`);
    console.log(`ðŸ“Š Expected avg profit: ${profile.metadata.avgProfit.toFixed(2)}%`);
    console.log(`ðŸŽ¯ Commands to execute: ${profile.commands.length}`);

    if (dryRun) {
      console.log('\nðŸ§ª DRY RUN - Commands that would be executed:');
      profile.executionChain.forEach((cmd, i) => {
        console.log(`  ${i + 1}. ${cmd}`);
      });
      return { success: true, dryRun: true, profile };
    }

    // Execute profile
    const results = {
      profile: profile.name,
      executed: [],
      failed: [],
      totalTime: 0
    };

    const startTime = Date.now();

    for (const command of profile.executionChain) {
      console.log(`\nðŸŽ¯ Executing: "${command}"`);

      try {
        const result = await this.hitch.processCommand(command, {
          source: 'profile',
          profileName: profile.name
        });

        results.executed.push({
          command: command,
          success: result.success,
          commandId: result.commandId
        });

        if (!result.success) {
          console.log(`âš ï¸ Command failed: ${result.error}`);
        }

      } catch (error) {
        results.failed.push({
          command: command,
          error: error.message
        });
        console.error(`âŒ Error executing command: ${error.message}`);
      }

      // Delay between commands
      if (sequential && delayBetween > 0) {
        await new Promise(resolve => setTimeout(resolve, delayBetween));
      }
    }

    results.totalTime = Date.now() - startTime;

    console.log('\nðŸ“Š Profile Execution Summary:');
    console.log(`âœ… Executed: ${results.executed.length}`);
    console.log(`âŒ Failed: ${results.failed.length}`);
    console.log(`â±ï¸ Total time: ${(results.totalTime / 1000).toFixed(1)}s`);

    return results;
  }

  /**
   * List available profiles
   */
  async listProfiles() {
    const files = await fs.readdir(this.profilesPath);
    const profiles = [];

    for (const file of files) {
      if (file.endsWith('.ogzprofile')) {
        try {
          const content = await fs.readFile(path.join(this.profilesPath, file), 'utf8');
          const profile = JSON.parse(content);

          profiles.push({
            filename: file,
            name: profile.name,
            created: profile.created,
            commands: profile.commands.length,
            avgProfit: profile.metadata.avgProfit,
            description: profile.description
          });
        } catch (error) {
          console.error(`Error reading profile ${file}:`, error);
        }
      }
    }

    return profiles.sort((a, b) => b.avgProfit - a.avgProfit);
  }

  /**
   * Create profile from specific command IDs
   */
  async createCustomProfile(profileName, commandIds, description = '') {
    const history = await this.hitch.logger.getCommandHistory();

    const selectedCommands = commandIds
      .map(id => history.find(cmd => cmd.id === id))
      .filter(Boolean);

    if (selectedCommands.length === 0) {
      throw new Error('No valid commands found with provided IDs');
    }

    const profile = {
      name: profileName,
      version: '1.0',
      created: new Date().toISOString(),
      description: description || `Custom profile with ${selectedCommands.length} selected commands`,
      metadata: {
        totalProfit: this.calculateTotalProfit(selectedCommands),
        avgProfit: this.calculateAvgProfit(selectedCommands),
        commandCount: selectedCommands.length,
        custom: true
      },
      commands: selectedCommands.map(cmd => ({
        input: cmd.input,
        sequence: cmd.id,
        impact: cmd.impact?.updates ? {
          percentChange: cmd.impact.updates[cmd.impact.updates.length - 1]?.percentChange || 0,
          trades: cmd.impact.updates[cmd.impact.updates.length - 1]?.tradesExecuted || 0
        } : null
      })),
      executionChain: selectedCommands.map(cmd => cmd.input)
    };

    const filename = `${profileName.toLowerCase().replace(/\s+/g, '_')}.ogzprofile`;
    const filepath = path.join(this.profilesPath, filename);

    await fs.writeFile(filepath, JSON.stringify(profile, null, 2));

    return {
      success: true,
      filepath: filepath,
      profile: profile
    };
  }

  /**
   * Helper methods
   */
  calculateTotalProfit(commands) {
    return commands.reduce((sum, cmd) => {
      if (!cmd.impact?.updates || cmd.impact.updates.length === 0) return sum;
      return sum + cmd.impact.updates[cmd.impact.updates.length - 1].percentChange;
    }, 0);
  }

  calculateAvgProfit(commands) {
    if (commands.length === 0) return 0;
    return this.calculateTotalProfit(commands) / commands.length;
  }

  extractConditions(commands) {
    const conditions = new Set();

    commands.forEach(cmd => {
      if (cmd.results?.applied) {
        cmd.results.applied.forEach(result => {
          if (result.type === 'rule' && result.rule) {
            conditions.add(JSON.stringify(result.rule));
          }
        });
      }
    });

    return Array.from(conditions).map(c => JSON.parse(c));
  }
}

// React Component for UI
const ProfileManager = ({ ogzPrime }) => {
  const [profiles, setProfiles] = React.useState([]);
  const [loading, setLoading] = React.useState(false);
  const [exportName, setExportName] = React.useState('');

  const exporter = React.useMemo(() => 
    new OGZProfileExporter(ogzPrime.hitch), [ogzPrime]
  );

  const loadProfiles = async () => {
    const profileList = await exporter.listProfiles();
    setProfiles(profileList);
  };

  const handleExport = async () => {
    if (!exportName) return;
    setLoading(true);

    try {
      await exporter.exportTopCommandsAsProfile(exportName, {
        minProfit: 1,
        maxCommands: 10
      });
      await loadProfiles();
      setExportName('');
    } catch (error) {
      console.error('Export failed:', error);
    } finally {
      setLoading(false);
    }
  };

  const handleExecute = async (filename) => {
    setLoading(true);
    try {
      const result = await exporter.importAndExecuteProfile(filename);
      console.log('Profile executed:', result);
    } catch (error) {
      console.error('Execution failed:', error);
    } finally {
      setLoading(false);
    }
  };

  React.useEffect(() => {
    loadProfiles();
  }, []);

  return (
    <div style={{ padding: '20px', background: '#000', color: '#00ff00' }}>
      <h3>ðŸ“¦ OGZ Profile Manager</h3>

      <div style={{ marginBottom: '20px' }}>
        <input
          type="text"
          value={exportName}
          onChange={(e) => setExportName(e.target.value)}
          placeholder="Profile name..."
          style={{ marginRight: '10px' }}
        />
        <button onClick={handleExport} disabled={loading}>
          Export Top Commands
        </button>
      </div>

      <div>
        <h4>Available Profiles:</h4>
        {profiles.map(profile => (
          <div key={profile.filename} style={{ marginBottom: '10px', padding: '10px', border: '1px solid #00ff00' }}>
            <strong>{profile.name}</strong> - {profile.commands} commands, {profile.avgProfit.toFixed(2)}% avg profit
            <button onClick={() => handleExecute(profile.filename)} style={{ marginLeft: '10px' }}>
              Execute
            </button>
          </div>
        ))}
      </div>
    </div>
  );
};

