    border: `2px solid #00ff00`,
    borderRadius: '5px',
    cursor: 'pointer',
    fontWeight: 'bold',
    fontSize: '14px',
    transition: 'all 0.3s'
  });

  const codeBlockStyle = {
    background: '#000',
    padding: '15px',
    borderRadius: '5px',
    border: '1px solid #333',
    fontFamily: 'monospace',
    fontSize: '12px',
    overflowX: 'auto'
  };

  if (!hitch) {
    return (
      <div style={containerStyle}>
        <div style={sectionStyle}>
          <h2>âš ï¸ Hitch not available</h2>
          <p>Please ensure Hitch is integrated into OGZPrime.</p>
        </div>
      </div>
