    const syntheticFeatures = enhanced.synthetic;
    const volatility = this.calculateVolatility(syntheticFeatures);
    const trend = this.calculateTrend(syntheticFeatures);

    let regime = 'NEUTRAL';
    if (volatility > 0.02 && Math.abs(trend) > 0.001) {
      regime = trend > 0 ? 'BULL_VOLATILE' : 'BEAR_VOLATILE';
    } else if (volatility < 0.01) {
      regime = 'RANGING';
    } else if (trend > 0.002) {
