</head>
<body>
    <div class="container">
        <h1>🧠 THE MOVER</h1>
        <p class="subtitle">AI Support Agent for OGZ Prime Trading System</p>
        
        <div class="status-bar">
            <div class="status-item">
                <span class="status-indicator" id="botStatus"></span>
                <span>Bot Connection</span>
            </div>
            <div class="status-item">
                <span class="status-indicator" id="voiceStatus"></span>
                <span>Voice Output</span>
            </div>
            <div class="status-item">
                <span id="personality">Personality: Loading...</span>
            </div>
        </div>
        
        <div class="controls">
            <button class="btn" onclick="toggleVoice()">Toggle Voice</button>
            <button class="btn" onclick="changePersonality()">Change Personality</button>
            <button class="btn" onclick="requestReport()">Get Report</button>
        </div>
        
        <div class="narration-feed" id="narrationFeed">
            <div style="text-align: center; color: #666;">Waiting for narrations...</div>
        </div>
        
        <div class="stats-grid">
            <div class="stat-card">
                <div class="stat-label">Trades Narrated</div>
                <div class="stat-value" id="tradesNarrated">0</div>
            </div>
            <div class="stat-card">
                <div class="stat-label">Session P&L</div>
                <div class="stat-value" id="sessionPL">$0.00</div>
            </div>
            <div class="stat-card">
                <div class="stat-label">Win Rate</div>
                <div class="stat-value" id="winRate">0%</div>
            </div>
            <div class="stat-card">
                <div class="stat-label">Current Regime</div>
                <div class="stat-value" id="marketRegime">-</div>
            </div>
        </div>
        
        <div class="houston-progress">
            <h2>🚀 Houston Fund Progress</h2>
            <div class="progress-bar">
                <div class="progress-fill" id="houstonProgress" style="width: 40%">
                    40% - $10,000 / $25,000
                </div>
            </div>
            <p style="text-align: center; color: #666;">Every trade brings Houston closer!</p>
        </div>
    </div>
    
    <script>
        let ws = null;
        let voiceEnabled = false;
        let currentPersonality = 'houston_focused';
        
        function connectWebSocket() {
            ws = new WebSocket('ws://localhost:4001');
            
            ws.onopen = () => {
                console.log('Connected to The Mover');
                document.getElementById('botStatus').classList.add('connected');
                
                // Subscribe to narrations
                ws.send(JSON.stringify({
                    type: 'subscribe'
                }));
            };
            
            ws.onmessage = (event) => {
                const data = JSON.parse(event.data);
                handleMessage(data);
            };
            
            ws.onclose = () => {
                document.getElementById('botStatus').classList.remove('connected');
                setTimeout(connectWebSocket, 5000);
            };
            
            ws.onerror = (error) => {
                console.error('WebSocket error:', error);
            };
        }
        
        function handleMessage(data) {
            switch (data.type) {
                case 'welcome':
                    document.getElementById('personality').textContent = `Personality: ${data.personality}`;
                    voiceEnabled = data.voiceEnabled;
                    updateVoiceStatus();
                    break;
                    
                case 'narration':
                    addNarration(data);
                    break;
                    
                case 'command_response':
                    if (data.response.runtime) {
                        updateStats(data.response);
                    }
                    break;
            }
        }
        
        function addNarration(narration) {
            const feed = document.getElementById('narrationFeed');
            
            // Clear initial message
            if (feed.children[0]?.style?.textAlign === 'center') {
                feed.innerHTML = '';
            }
            
            const item = document.createElement('div');
            item.className = 'narration-item';
            
            // Add profit/loss class
            if (narration.content.includes('Profit') || narration.content.includes('Winner')) {
                item.classList.add('profit');
            } else if (narration.content.includes('Loss') || narration.content.includes('Stop triggered')) {
                item.classList.add('loss');
            }
            
            const time = new Date().toLocaleTimeString();
            item.innerHTML = `
                <div class="narration-time">${time}</div>
                <div>${narration.content}</div>
            `;
            
            feed.appendChild(item);
            feed.scrollTop = feed.scrollHeight;
            
            // Keep only last 50 narrations
            while (feed.children.length > 50) {
                feed.removeChild(feed.firstChild);
            }
        }
        
        function updateStats(report) {
            document.getElementById('tradesNarrated').textContent = report.tradesNarrated || '0';
            document.getElementById('sessionPL').textContent = `$${report.profitLoss || '0.00'}`;
            document.getElementById('winRate').textContent = report.winRate || '0%';
            document.getElementById('marketRegime').textContent = report.currentRegime || '-';
            
            // Update Houston progress
            if (report.houstonProgress) {
                const progress = parseFloat(report.houstonProgress);
                const progressBar = document.getElementById('houstonProgress');
                progressBar.style.width = `${progress}%`;
                progressBar.textContent = `${progress}% - $${(progress * 250).toFixed(0)} / $25,000`;
            }
        }
        
        function toggleVoice() {
            fetch('http://localhost:4000/voice/toggle', { method: 'POST' })
                .then(res => res.json())
                .then(data => {
                    voiceEnabled = data.voiceEnabled;
                    updateVoiceStatus();
                });
        }
        
        function updateVoiceStatus() {
            const indicator = document.getElementById('voiceStatus');
            if (voiceEnabled) {
                indicator.classList.add('connected');
            } else {
                indicator.classList.remove('connected');
            }
        }
        
        function changePersonality() {
            const personalities = ['professional_trader', 'aggressive_trader', 'zen_master', 'houston_focused'];
            const current = personalities.indexOf(currentPersonality);
            const next = (current + 1) % personalities.length;
            currentPersonality = personalities[next];
            
            ws.send(JSON.stringify({
                type: 'command',
                command: `personality ${currentPersonality}`
            }));
            
            document.getElementById('personality').textContent = `Personality: ${currentPersonality}`;
        }
        
        function requestReport() {
            ws.send(JSON.stringify({
                type: 'command',
                command: 'status'
            }));
        }
        
        // Initial connection
        connectWebSocket();
        
        // Periodic report updates
        setInterval(requestReport, 30000);
    </script>
</body>
</html>

/**
 * BUG HUNTER - Systematic Testing Framework for OGZ Prime
 * 
 * This tool systematically probes your trading system to expose bugs
 * before they can cost you real money.
 * 
 * Usage: node BugHunter.js [test-name]
 */

const EventEmitter = require('events');

class BugHunter extends EventEmitter {
  constructor(ogzPrime) {
    super();
    this.bot = ogzPrime;
    this.results = {
      passed: [],
      failed: [],
      warnings: []
    };

    console.log('🔍 BUG HUNTER INITIALIZED - Let\'s find those bugs!');
  }

  /**
   * Run all tests
   */
  async runAllTests() {
    console.log('🎯 Starting comprehensive bug hunt...\n');

    // 1. Connection Tests
    await this.testConnectionResilience();

    // 2. Data Flow Tests
    await this.testDataFlow();

    // 3. Trading Logic Tests
    await this.testTradingLogic();

    // 4. Memory Tests
    await this.testMemoryLeaks();

    // 5. Edge Case Tests
    await this.testEdgeCases();

    // 6. Chaos Tests
    await this.testChaosScenarios();

    // Report
    this.generateReport();
  }

  /**
   * TEST 1: Connection Resilience
   */
  async testConnectionResilience() {
    console.log('📡 TESTING CONNECTION RESILIENCE...');

    // Test 1.1: Kill data feed
    await this.test('Data Feed Death', async () => {
      const originalInterval = this.bot.simulationInterval;

      // Kill the feed
      clearInterval(this.bot.simulationInterval);
      this.bot.simulationInterval = null;

      // Wait and check if it recovers
      await this.wait(35000); // Wait for stale timeout

      // Check if feed restarted
      if (!this.bot.simulationInterval) {
        throw new Error('Data feed did not auto-recover after death');
      }

      // Restore
      this.bot.simulationInterval = originalInterval || this.bot.simulationInterval;
    });

    // Test 1.2: WebSocket disruption
    await this.test('WebSocket Server Crash', async () => {
      const port = this.bot.config.dataWebSocketPort;
      const server = this.bot.webSocketManager.getServer(port);

      // Force close the server
      server.close();

      // Wait for recovery
      await this.wait(5000);

      // Check if new server was created
      const newServer = this.bot.webSocketManager.getServer(port);
      if (!newServer) {
        throw new Error('WebSocket server did not recover');
      }
    });

    // Test 1.3: Rapid reconnections
    await this.test('Rapid Disconnection Storm', async () => {
      for (let i = 0; i < 5; i++) {
        clearInterval(this.bot.simulationInterval);
        await this.wait(100);
        this.bot.simulateMarketData();
        await this.wait(100);
      }

      // System should still be stable
      if (!this.bot.simulationInterval) {
        throw new Error('System unstable after rapid reconnections');
      }
    });
  }

  /**
   * TEST 2: Data Flow Integrity
   */
  async testDataFlow() {
    console.log('\n📊 TESTING DATA FLOW...');

    // Test 2.1: Data timestamp accuracy
    await this.test('Data Timestamp Integrity', async () => {
      const timestamps = [];

      // Collect 10 ticks
      const collector = (tick) => {
        timestamps.push(tick.timestamp);
      };
      this.bot.on('market_data_update', collector);

      await this.wait(10000);
      this.bot.off('market_data_update', collector);

      // Check timestamps are sequential and recent
      for (let i = 1; i < timestamps.length; i++) {
        if (timestamps[i] <= timestamps[i-1]) {
          throw new Error('Non-sequential timestamps detected');
        }
        if (Date.now() - timestamps[i] > 5000) {
          throw new Error('Stale timestamp detected in data flow');
        }
      }
    });

    // Test 2.2: Data validation
    await this.test('Invalid Data Handling', async () => {
      // Send invalid data
      const invalidData = [
        { price: -100 },      // Negative price
        { price: 0 },         // Zero price
        { price: null },      // Null price
        { price: 'abc' },     // String price
        { price: Infinity },  // Infinite price
        { price: 1000000 },   // Extreme price
        {}                    // Missing price
      ];

      for (const data of invalidData) {
        try {
          this.bot.processTick(data);
        } catch (error) {
          // Good - it should throw or handle gracefully
        }

        // Check system is still stable
        if (!this.bot.marketData || this.bot.marketData.price <= 0) {
          throw new Error(`Invalid data corrupted system: ${JSON.stringify(data)}`);
        }
      }
    });
  }

  /**
   * TEST 3: Trading Logic Bombs
   */
  async testTradingLogic() {
    console.log('\n💰 TESTING TRADING LOGIC...');

    // Test 3.1: Rapid price movements
    await this.test('Flash Crash Handling', async () => {
      const startPrice = this.bot.marketData.price;

      // Simulate 50% flash crash
      this.bot.processTick({ 
        price: startPrice * 0.5, 
        timestamp: Date.now() 
      });

      // Check if position was protected
      if (this.bot.tradingBrain.isInPosition()) {
        const position = this.bot.tradingBrain.currentPosition;
        if (!position.stopLoss || position.stopLoss < startPrice * 0.8) {
          throw new Error('Stop loss not adjusted for flash crash');
        }
      }

      // Restore normal price
      this.bot.processTick({ 
        price: startPrice, 
        timestamp: Date.now() 
      });
    });

    // Test 3.2: Balance edge cases
    await this.test('Zero Balance Handling', async () => {
      const originalBalance = this.bot.riskManager.currentBalance;

      // Set balance to near zero
      this.bot.riskManager.currentBalance = 0.01;

      // Try to trade
      const canTrade = this.bot.tradingBrain.evaluateTradingOpportunity();

      if (canTrade && this.bot.tradingBrain.shouldEnterPosition()) {
        throw new Error('System tried to trade with zero balance');
      }

      // Restore
      this.bot.riskManager.currentBalance = originalBalance;
    });

    // Test 3.3: Multiple simultaneous signals
    await this.test('Signal Conflict Resolution', async () => {
      // Force conflicting signals
      this.bot.patterns.currentPattern = 'BREAKOUT';
      this.bot.indicators.rsi = 75; // Overbought
      this.bot.indicators.trend = 'DOWN';

      // Should not enter position with conflicts
      if (this.bot.tradingBrain.shouldEnterPosition()) {
        throw new Error('Entered position with conflicting signals');
      }
    });
  }

  /**
   * TEST 4: Memory Leaks
   */
  async testMemoryLeaks() {
    console.log('\n🧠 TESTING MEMORY MANAGEMENT...');

    await this.test('Memory Leak Detection', async () => {
      const startMemory = process.memoryUsage().heapUsed;

      // Simulate 1000 trades rapidly
      for (let i = 0; i < 1000; i++) {
        this.bot.processTick({
          price: 50000 + Math.random() * 1000,
          timestamp: Date.now()
        });

        if (i % 100 === 0) {
          // Force garbage collection if exposed
          if (global.gc) global.gc();
        }
      }

      const endMemory = process.memoryUsage().heapUsed;
      const memoryGrowth = endMemory - startMemory;

      // Alert if memory grew by more than 50MB
      if (memoryGrowth > 50 * 1024 * 1024) {
        this.warn(`Potential memory leak: ${(memoryGrowth / 1024 / 1024).toFixed(2)}MB growth`);
      }
    });
  }

  /**
   * TEST 5: Edge Cases
   */
  async testEdgeCases() {
    console.log('\n🔪 TESTING EDGE CASES...');

    // Test 5.1: Market open/close boundaries
    await this.test('Market Boundary Handling', async () => {
      // Simulate market close
      const friday4pm = new Date();
      friday4pm.setDay(5); // Friday
      friday4pm.setHours(16, 0, 0, 0); // 4 PM

      // Override time
      const originalNow = Date.now;
      Date.now = () => friday4pm.getTime();

      // Should not trade
      if (this.bot.tradingBrain.shouldEnterPosition()) {
        throw new Error('Attempted to trade at market close');
      }

      // Restore
      Date.now = originalNow;
    });

    // Test 5.2: Extreme indicator values
    await this.test('Extreme Indicator Values', async () => {
      const extremeValues = {
        rsi: [0, 100, -10, 110],
        macd: [-1000, 1000, NaN, Infinity],
        volume: [0, -100, 999999999]
      };

      for (const [indicator, values] of Object.entries(extremeValues)) {
        for (const value of values) {
          this.bot.indicators[indicator] = value;

          // Should handle gracefully
          try {
            this.bot.tradingBrain.evaluateTradingOpportunity();
          } catch (error) {
            throw new Error(`Failed on ${indicator}=${value}: ${error.message}`);
          }
        }
      }
    });
  }

  /**
   * TEST 6: Chaos Engineering
   */
  async testChaosScenarios() {
    console.log('\n🌪️  TESTING CHAOS SCENARIOS...');

    // Test 6.1: Everything fails at once
    await this.test('Cascading Failure', async () => {
      // Kill data feed
      clearInterval(this.bot.simulationInterval);

      // Corrupt indicators
      this.bot.indicators = null;

      // Break WebSocket
      const port = this.bot.config.dataWebSocketPort;
      this.bot.webSocketManager.closeServer(port);

      // Wait for recovery
      await this.wait(10000);

      // System should have recovered or be in safe mode
      if (!this.bot.connectionResilience) {
        throw new Error('System did not recover from cascading failure');
      }
    });

    // Test 6.2: Random chaos
    await this.test('Random Chaos Monkey', async () => {
      const chaosActions = [
        () => this.bot.marketData.price = null,
        () => this.bot.patterns.currentPattern = 'INVALID_PATTERN',
        () => this.bot.riskManager.currentBalance = -1000,
        () => clearInterval(this.bot.simulationInterval),
        () => this.bot.indicators.trend = null
      ];

      // Run 10 random chaos actions
      for (let i = 0; i < 10; i++) {
        const action = chaosActions[Math.floor(Math.random() * chaosActions.length)];
        try {
          action();
        } catch (error) {
          // Expected - system should handle gracefully
        }
        await this.wait(100);
      }

      // System should still be functional
      if (!this.bot.marketData || typeof this.bot.marketData.price !== 'number') {
        throw new Error('System corrupted by chaos testing');
      }
    });
  }

  /**
   * Helper: Run a single test
   */
  async test(name, testFn) {
    try {
      console.log(`  🧪 ${name}...`);
      await testFn();
      console.log(`  ✅ ${name} - PASSED`);
      this.results.passed.push(name);
    } catch (error) {
      console.log(`  ❌ ${name} - FAILED: ${error.message}`);
      this.results.failed.push({ name, error: error.message });
    }
  }

  /**
   * Helper: Add warning
   */
  warn(message) {
    console.log(`  ⚠️  WARNING: ${message}`);
    this.results.warnings.push(message);
  }

  /**
   * Helper: Wait for milliseconds
   */
  wait(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }

  /**
   * Generate final report
   */
  generateReport() {
    console.log('\n' + '='.repeat(60));
    console.log('📋 BUG HUNT REPORT');
    console.log('='.repeat(60));

    console.log(`\n✅ PASSED: ${this.results.passed.length} tests`);
    this.results.passed.forEach(test => console.log(`   - ${test}`));

    if (this.results.warnings.length > 0) {
      console.log(`\n⚠️  WARNINGS: ${this.results.warnings.length}`);
      this.results.warnings.forEach(warn => console.log(`   - ${warn}`));
    }

    if (this.results.failed.length > 0) {
      console.log(`\n❌ FAILED: ${this.results.failed.length} tests`);
      this.results.failed.forEach(({ name, error }) => {
        console.log(`   - ${name}: ${error}`);
      });

      console.log('\n🔧 RECOMMENDATIONS:');
      console.log('1. Fix failed tests before running with real money');
      console.log('2. Add error handling for edge cases discovered');
      console.log('3. Implement additional monitoring for warnings');
    } else {
      console.log('\n🎉 ALL TESTS PASSED! Your bot is battle-tested!');
    }

    console.log('\n' + '='.repeat(60));
  }
}

